create schema stratiq_private; revoke all on schema stratiq_private from public, anon, authenticated, service_role; alter default privileges in schema stratiq_private revoke all on tables from public, anon, authenticated, service_role; alter default privileges in schema stratiq_private revoke execute on functions from public, anon, authenticated, service_role; create table stratiq_private.company (id uuid primary key default gen_random_uuid(), legal_name text not null check(length(trim(legal_name))>0)); alter table stratiq_private.company enable row level security; revoke all on stratiq_private.company from public, anon, authenticated, service_role;
